"""Independent, hand-computed arithmetic checks — not generated by the engine.
These three numbers were worked out by hand against the formula in the design doc
(Premise 3) before being compared to compute_quote()'s output, specifically so a bug
in quote.py can't silently "pass" by agreeing with itself.
"""
import datetime as dt

from app.db import load_creators_from_csv
from app.models import Deliverable

CREATORS = {c.id: c for c in load_creators_from_csv()}


def test_lumiere_skin_co_fully_specified():
    """2 reels + 2 stories for Aanya Mehra (reel ₹62,000, story ₹18,000, 10% bundle
    discount at >=3 deliverables), no usage overreach, no whitelisting, no exclusivity.

    base = 2*62,000 + 2*18,000 = 124,000 + 36,000 = 160,000
    count = 4 >= 3 -> bundle discount applies: 160,000 * 0.90 = 144,000
    no surcharges -> total = 144,000
    """
    from app.quote import compute_quote

    aanya = CREATORS["aanya_mehra"]
    q = compute_quote(
        aanya,
        [Deliverable("reel", 2), Deliverable("story", 2)],
        usage_rights_days=30, whitelisting=False, exclusivity_requested=False,
    )
    assert q.base == 160000.0
    assert q.bundle_discount_applied is True
    assert q.after_discount == 144000.0
    assert q.total == 144000.0


def test_nivara_soaps_conflict_with_surcharges():
    """2 reels + 3 stories for Aanya Mehra, 90-day usage (30-day default, 60-day
    overage -> 2 extra 30-day blocks), whitelisting requested, no exclusivity.

    base = 2*62,000 + 3*18,000 = 124,000 + 54,000 = 178,000
    count = 5 >= 3 -> bundle discount: 178,000 * 0.90 = 160,200
    usage overage = 90 - 30 = 60 -> ceil(60/30) = 2 blocks -> +40%: 160,200 * 0.40 = 64,080
    whitelisting +25%: 160,200 * 0.25 = 40,050
    exclusivity: not requested -> +0
    total = 160,200 + 64,080 + 40,050 = 264,330
    """
    from app.quote import compute_quote

    aanya = CREATORS["aanya_mehra"]
    q = compute_quote(
        aanya,
        [Deliverable("reel", 2), Deliverable("story", 3)],
        usage_rights_days=90, whitelisting=True, exclusivity_requested=False,
    )
    assert q.base == 178000.0
    assert q.after_discount == 160200.0
    assert q.usage_extra_blocks == 2
    assert q.usage_fee_amount == 64080.0
    assert q.whitelisting_fee_amount == 40050.0
    assert q.exclusivity_fee_amount == 0.0
    assert q.total == 264330.0


def test_gearfit_single_reel_no_bundle():
    """1 reel for Rohan Iyer (reel ₹48,000). Only 1 deliverable, below the
    bundle_discount_min_deliverables threshold (3), so no discount applies and the
    quote is simply the rate-card figure.
    """
    from app.quote import compute_quote

    rohan = CREATORS["rohan_iyer"]
    q = compute_quote(
        rohan,
        [Deliverable("reel", 1)],
        usage_rights_days=30, whitelisting=False, exclusivity_requested=False,
    )
    assert q.base == 48000.0
    assert q.bundle_discount_applied is False
    assert q.total == 48000.0


def test_counter_offer_rounds_to_nearest_1000():
    from app.quote import round_counter_offer

    assert round_counter_offer(69920.0) == 70000
    assert round_counter_offer(69499.0) == 69000
    assert round_counter_offer(69500.0) == 70000 or round_counter_offer(69500.0) == 69000  # banker's rounding edge
